import numpy as np

def log_so3(R: np.ndarray) -> np.ndarray:
    tr = np.trace(R)
    cos_theta = np.clip((tr - 1.0) / 2.0, -1.0, 1.0)
    theta = np.arccos(cos_theta)

    if np.abs(theta) < 1e-10:
        return np.zeros(3)

    # Skew-symmetric part: (R - R^T) / (2 * sin(theta))
    factor = theta / (2.0 * np.sin(theta))
    omega_x = factor * (R[2, 1] - R[1, 2])
    omega_y = factor * (R[0, 2] - R[2, 0])
    omega_z = factor * (R[1, 0] - R[0, 1])
    return np.array([omega_x, omega_y, omega_z])
